import fitz

doc = fitz.open("/root/sc100-filled.pdf")
check_fields = [
    'SC-100[0].Page2[0].List1[0].Item1[0].PlaintiffName1[0]',
    'SC-100[0].Page2[0].List3[0].PlaintiffClaimAmount1[0]',
    'SC-100[0].Page3[0].List4[0].Item4[0].Checkbox50[0]'
]

for page in doc:
    for field in page.widgets():
        if field.field_name in check_fields:
            print(f"'{field.field_name}': {field.field_value}")
doc.close()
